import { describe, it, expect } from '@jest/globals';
import bcrypt from 'bcryptjs';
import { hashPassword, verifyPassword } from '../../src/middleware/auth';

describe('Debug Password Hashing', () => {
  it('should test bcrypt directly', async () => {
    const password = 'TestPassword123!';
    
    // Test direct bcrypt
    const directHash = await bcrypt.hash(password, 10);
    const directVerify = await bcrypt.compare(password, directHash);
    
    console.log('Direct bcrypt hash:', directHash);
    console.log('Direct bcrypt verify:', directVerify);
    
    expect(directVerify).toBe(true);
  });
  
  it('should test auth middleware functions', async () => {
    const password = 'TestPassword123!';
    
    // Test middleware functions
    const hash = await hashPassword(password);
    const verify = await verifyPassword(password, hash);
    
    console.log('Middleware hash:', hash);
    console.log('Middleware verify:', verify);
    
    expect(verify).toBe(true);
  });
  
  it('should verify a known hash', async () => {
    const password = 'ValidPass123!';
    const knownHash = '$2a$10$validhashedpassword'; // This is from the test
    
    try {
      const result = await bcrypt.compare(password, knownHash);
      console.log('Known hash verification:', result);
    } catch (error) {
      console.log('Error verifying known hash:', error);
    }
  });
});